create or replace function integration_manual_assignment(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare job uuid; property uuid:=(p_input->>'property_id')::uuid; calendar text:=p_input->>'calendar'; saved_pay numeric;
begin
 if not exists(select 1 from profiles where id=p_actor and role::text='admin' and status='active') then raise exception 'active_admin_required';end if;
 if calendar not in ('commercial','residential') or length(trim(coalesce(p_input->>'reason','')))<5 or length(trim(coalesce(p_input->>'title','')))=0 or length(trim(coalesce(p_input->>'property_name','')))=0 or length(trim(coalesce(p_input->>'address','')))=0 or (p_input->>'pay_amount')::numeric<0 or (p_input->>'pay_amount')::numeric<>round((p_input->>'pay_amount')::numeric,2) or (p_input->>'end_window')::timestamptz<=(p_input->>'start_window')::timestamptz then raise exception 'invalid_assignment';end if;
 if property is not null and not exists(select 1 from portal_properties where id=property) and not exists(select 1 from clients where id=property) and not exists(select 1 from properties where id=property) then raise exception 'property_not_found';end if;
 if calendar='residential' and coalesce((p_input->>'customer_price')::numeric,0)<=0 then raise exception 'residential_customer_price_required_for_36_percent_pay';end if;
 insert into assignment_blocks(title,property_id,portal_property_id,property_name,address,service_type,scope,pay_amount,start_window,end_window,status,visibility,unit_number,unit_name,qr_tracker_id,special_instructions,created_by,metadata)
 values(p_input->>'title',property,case when exists(select 1 from portal_properties where id=property) then property end,p_input->>'property_name',p_input->>'address',coalesce(p_input->>'service_type','Cleaning'),p_input->>'scope',(p_input->>'pay_amount')::numeric,(p_input->>'start_window')::timestamptz,(p_input->>'end_window')::timestamptz,'pending','pending',coalesce(p_input->>'unit_number',''),coalesce(p_input->>'unit_number',''),p_input->>'qr_tracker_id',p_input->>'special_instructions',p_actor,jsonb_build_object('scope_type',calendar,'source','admin_manual_api','creation_reason',p_input->>'reason','customer_price',p_input->'customer_price')) returning id,pay_amount into job,saved_pay;
 return jsonb_build_object('id',job,'calendar',calendar,'status','pending','pay_amount',saved_pay,'customer_booking_created',false,'customer_charged',false);
end $$;
revoke all on function integration_manual_assignment(uuid,jsonb) from public,anon,authenticated;grant execute on function integration_manual_assignment(uuid,jsonb) to service_role;
